  FROM mi_daily_closes
 WHERE ticker IN ('A','AAOI','AAON','ACMR','ACNT','ACOG','ADPT','AEHL','AEIS','AFYA','AGBK','AGL','AIOS','AIP','AIRO','AIXI','AKAM','AKAN','ALAB','ALB','ALGS','ALMU','AMCI','AMD','AMLX','AMRC','AMWL','APPS','ARCO','ARCT','ARLO','ARM','ARRY','ARTV','ASPI','ASTC','ASX','ASYS','ATRA','AU','AVAH','AVAV','AVTX','AXIL','AXTI','AXTU','BAX','BBSI','BCS','BDSX','BFLY','BGDE','BIAF','BIRD','BLBD','BLLN','BLMN','BLZE','BNAI','BNTX','BOOM','BOXL','BRUN','BRUNW','BTGO','BW','BZH','CALY','CART','CAST','CAT','CCOI','CCRN','CEVA','CGAU','CGCT','CHA','CHPT','CMC','CMCO','COAG','CODX','COHR','COMP','CORT','CPS','CPSH','CRMD','CRML','CRSR','CRWV','CSCO','CTRN','CVKD','CXDO','CYTK','DAAQ','DASH','DBGI','DBVT','DDOG','DELL','DFNS','DGII','DGXX','DLTR','DOCN','DOCS','DPRO','DRD','DRTS','DT','DUKR','DV','DXYZ','EIKN','EL','ELA','ELPC','ELPW','EME','ENHA','EOSE','ERNA','ESLT','ETON','EVER','EWTX','EXK','EZPW','FCEL','FGNX','FIGS','FJET','FLEX','FLNC','FLR','FLY','FLYW','FN','FNKO','FORM','FOUR','FPS','FRD','FROG','FTK','FTNT','FTRE','GEO','GFI','GIG','GKOS','GLIBK','GO','GPK','GRML','GSIT','GTE','GWW','HAE','HCM','HII','HIMX','HLIT','HMY','HNGE','HNRG','HPE','HTCO','HTFL','HTLD','HUT','HWM','HYMC','IAG','IART','IBTA','ICL','IMC','IMOS','IMXI','INBX','INFU','INOD','INSP','INTR','INTT','IPGP','IPST','IPWR','IREN','ITUB','IX','JFB','JLHL','JMIA','JOYY','KC','KGS','KLAR','KLIC','KMT','KODK','KSS','KTOS','LASR','LFST','LFVN','LGN','LICN','LIFE','LITE','LPTH','LRCX','LTRX','LWLG','MASS','MCHP','MDB','MED','MITK','MKSI','MKTX','MNDY','MNTS','MOD','MRAM','MRNA','MRVI','MRVL','MT','MTSI','MTW','MWC','MX','MXL','NAMS','NBIS','NBTX','NDLS','NEOG','NET','NG','NTAP','NTRA','NTSK','NU','NVAX','NVEC','NVST','NVTS','NXT','OBX','OCC','ONDS','ONTO','ORA','OSCR','OSPN','P','PAGS','PAR','PBM','PBR','PCT','PCVX','PD','PDYN','PENG','PGNY','PGY','PHOE','PHR','PICS','PINS','PLOW','PLRZ','PLTR','PN','POET','PONY','PRCH','PRGO','PSFE','PSIX','PSNL','PSTV','PTC','PTON','PUBM','PWR','QCOM','QLYS','QNST','QNTM','QS','